    explicit Fixture(const std::filesystem::path& package):pin(Pin(package)){SemanticBridgeTestAccess::ObserveContext(*bridge,SemanticContextKind::Runtime,1,1);SemanticBridgeTestAccess::ObserveContext(*bridge,SemanticContextKind::City,7,3);base=std::make_shared<BaseHost>(package,pin,std::function<void(ScriptPhase,std::uint64_t)>{},bridge);Check(base->Ready(),"actual Base ready");Write();manager=std::make_unique<ModManager>(root/"mods",root/"state.toon",registry,cache,RuntimeResourceRefreshCallback{},ScriptScheduler::LogSink{},nullptr,domain);std::string error;Check(manager->Initialize(error),"actual manager initialized");Check(Publication::Enroll(*manager)==ScopeResult::Ok,"actual scheduler enrolled");}
