    ~Fixture(){manager.reset();base.reset();std::error_code error;std::filesystem::remove_all(root,error);}
    /** @summary Write one supported source generation. @param body Actual Luau source. */
    void Write(const std::string& body="return {onTick=function() end,onDisable=function() end}"){const auto directory=root/"mods"/"fixture.owner";std::filesystem::create_directories(directory/"scripts");sc13::tests::WriteTextFile(directory/"mod.toml",sc13::tests::FixtureHeader("fixture.owner","VM enrollment")+"[scripts]\nlanguage='luau'\nentry='scripts/init.luau'\nmemoryMiB=2\nbudgetMs=20\n"+sc13::tests::FixturePatch(3));sc13::tests::WriteTextFile(directory/"scripts/init.luau",body);}
