/** @summary Make a real standalone VM solely to occupy the existing shared lane. @return Native unbound VM. */
std::shared_ptr<ScriptRuntime> Standalone(){ScriptDefinition definition;definition.entry="scripts/standalone.luau";definition.language="luau";definition.memoryBytes=2U*1024U*1024U;definition.budgetMs=20;definition.bytecode=Luau::compile("return {onTick=function() end,onDisable=function() end}");return std::make_shared<ScriptRuntime>("standalone",definition);}
/** @summary Observe original host inventory via the existing bounded close foundation, never a VM closure certificate. @param token Exact close owner. @return Current partial observation. */
ManagerClose::Observation Inventory(ManagerClose::Token& token){ManagerClose::Observation value;Await([&]{value=ManagerClose::Poll(token);Check(value.checked<=32,"at most32 existing slots visited per inventory poll");Check(value.remainingRetirement&&!value.finalizable,"inventory is not resource retirement");return value.phase==ManagerClose::Phase::FoundationReady;},"bounded actual host inventory ready");return value;}
/** @summary Verify returned preparation identity and exact same-host idempotence with no operational effect. @param package Actual Base. */
void Returned(const std::filesystem::path& package){Fixture fixture(package);const auto registry=fixture.registry.Current();const auto revision=fixture.domain->Revision();auto stamp=Lifetime::Capture(*fixture.manager,"fixture.owner");auto plan=fixture.Candidate();auto vm=Preparation::Vm(plan);Check(Preparation::Binding(*fixture.manager,vm)==ScopeResult::Ok,"returned uncommitted candidate enrolled in original native host");const auto before=Close::Controls(vm);Check(before.generation!=0&&before.revision!=0,"actual original slot generation and host activity");Check(Preparation::Bind(*fixture.manager,vm)==ScopeResult::Ok,"same-host private binding idempotent");Check(Close::Controls(vm).revision==before.revision,"idempotent binding does not mutate topology");bool denied{};try{Close::Scheduler(*fixture.manager).Prepare(vm);}catch(const std::exception&){denied=true;}Check(denied,"ordinary Prepare still rejects already-bound VM");denied=false;try{vm->Commit();}catch(const std::exception&){denied=true;}Check(denied,"private enrollment does not permit direct Commit");Check(!Preparation::Scope(plan)->Current().activationCommitted&&fixture.registry.Current()==registry&&fixture.domain->Revision()==revision,"enrollment grants no activation or publication");Check(Lifetime::Validate(stamp)==ScopeResult::Ok&&!fixture.manager->Snapshot().front().scriptRunning,"canonical stamp and operational projection unchanged");auto handle=Close::Capture(*fixture.manager);Check(ManagerClose::Request(handle)==ScopeResult::Ok,"inventory request");ManagerClose::Token token;Check(ManagerClose::Acquire(handle,token)==ScopeResult::Ok,"inventory owner");Check(Inventory(token).holders==1,"uncommitted returned VM included, Base excluded");Check(!Scheduler::Closed(vm),"inventory does not close VM");}
/** @summary Exercise genuine unbound queued/executing controls and actual L contention before same-host binding. @param package Actual Base. */
void WorkAndLocks(const std::filesystem::path& package){Fixture fixture(package);auto capture=fixture.Capture();std::atomic_uint seam{};Preparation::BeforeBind([&](const std::shared_ptr<ScriptRuntime>& vm){++seam;Check(Preparation::Binding(*fixture.manager,vm)==ScopeResult::NotReady,"actual candidate unassociated at genuine seam");auto blocker=Standalone();Gate active;auto first=std::async(std::launch::async,[&]{Close::InvokeControl(blocker,[&]{active.Pause();});});active.Wait();auto queued=std::async(std::launch::async,[&]{Close::InvokeControl(vm,[]{});});Await([&]{return Close::Controls(vm).queued==1;},"actual unbound candidate control queued");Check(Preparation::Bind(*fixture.manager,vm)==ScopeResult::Busy,"queued unbound Work prevents binding");Check(Preparation::Binding(*fixture.manager,vm)==ScopeResult::NotReady,"queued Busy leaves both associations unchanged");active.Release();Check(first.wait_for(2s)==std::future_status::ready&&queued.wait_for(2s)==std::future_status::ready,"queued original controls acknowledged");first.get();queued.get();blocker.reset();Gate executing;auto control=std::async(std::launch::async,[&]{Close::InvokeControl(vm,[&]{executing.Pause();});});executing.Wait();Check(Close::Controls(vm).executing==1,"actual candidate Work executing");Check(Preparation::Bind(*fixture.manager,vm)==ScopeResult::Busy,"executing unbound Work prevents binding");Check(Preparation::Binding(*fixture.manager,vm)==ScopeResult::NotReady,"executing Busy leaves association unchanged");executing.Release();Check(control.wait_for(2s)==std::future_status::ready,"executing control acknowledged before borrowed seam returns");control.get();Preparation::HoldLane(*fixture.manager,[&]{auto attempt=std::async(std::launch::async,[&]{return Preparation::Bind(*fixture.manager,vm);});Check(attempt.wait_for(1s)==std::future_status::ready,"actual L contention returns promptly");Check(attempt.get()==ScopeResult::Busy,"actual try-L is Busy");});Check(Preparation::Binding(*fixture.manager,vm)==ScopeResult::NotReady,"try-L Busy cannot half-bind");});auto plan=Publication::Candidate(*fixture.manager,capture,fixture.base);Preparation::BeforeBind({});Check(seam==1&&Preparation::Binding(*fixture.manager,Preparation::Vm(plan))==ScopeResult::Ok,"real candidate binds after all original control acknowledgements");}
/** @summary Close at the exact after-first-Current/before-Bind seam with original Lease still counted. @param package Actual Base. */
void CloseRace(const std::filesystem::path& package){Fixture fixture(package);const auto originalRegistry=fixture.registry.Current();auto handle=Close::Capture(*fixture.manager);auto capture=fixture.Capture();Gate seam;std::weak_ptr<ScriptRuntime> weak;auto work=std::async(std::launch::async,[&]{Preparation::BeforeBind([&](const std::shared_ptr<ScriptRuntime>& vm){weak=vm;seam.Pause();});try{auto result=Publication::Candidate(*fixture.manager,capture,fixture.base);Preparation::BeforeBind({});return std::string("unexpected preparation success");}catch(const std::runtime_error& error){Preparation::BeforeBind({});return std::string(error.what());}});seam.Wait();Check(ManagerClose::Request(handle)==ScopeResult::Ok,"close wins before real binding");ManagerClose::Token token;Check(ManagerClose::Acquire(handle,token)==ScopeResult::Ok,"close owner during admitted preparation");auto pending=ManagerClose::Poll(token);Check(pending.users>=1&&pending.phase!=ManagerClose::Phase::FoundationReady,"actual native constructor borrower blocks close readiness");seam.Release();Check(work.wait_for(2s)==std::future_status::ready,"closed preparation abort acknowledges");/** @summary Report only the joined native error and copied passive facts on the main thread, without retaining a candidate owner or changing the exact close oracle. */const auto outcome=work.get();std::cerr<<"VM enrollment close race outcome="<<outcome<<" candidateAlive="<<(!weak.expired())<<" admittedUsers="<<pending.users<<std::endl;Check(outcome=="preparation.closed","true close seam rejects unexposed candidate");Check(weak.expired(),"aborted candidate actual slot owner reclaimed before Lease exit");Check(Inventory(token).holders==0,"closed abort leaves no original host holder");Check(fixture.domain->Revision()==0&&fixture.registry.Current()==originalRegistry&&fixture.manager->Snapshot().empty(),"closed binding preserves registry and rejects new public readers");}
/** @summary Deny foreign native hosts and keep unrelated manager/Base inventory separate. @param package Actual Base. */
void Foreign(const std::filesystem::path& package){Fixture fixture(package);std::filesystem::create_directories(fixture.root/"othermods");PatchRegistry registry;RuntimeResourceCache cache;ModManager other(fixture.root/"othermods",fixture.root/"other-state.toon",registry,cache);std::string error;Check(other.Initialize(error),"other actual manager initialized");auto plan=fixture.Candidate();auto vm=Preparation::Vm(plan);Check(Preparation::Bind(other,vm)==ScopeResult::Denied,"foreign host cannot adopt enrolled preparation");Check(Preparation::Binding(*fixture.manager,vm)==ScopeResult::Ok,"foreign denial preserves original association");auto otherVm=Standalone();Close::Scheduler(other).Prepare(otherVm);auto standalone=Standalone();Check(Preparation::Bind(*fixture.manager,otherVm)==ScopeResult::Denied&&Preparation::Bind(*fixture.manager,standalone)==ScopeResult::Denied,"ordinary/foreign VM role cannot become preparation");auto handle=Close::Capture(*fixture.manager);ManagerClose::Request(handle);ManagerClose::Token token;Check(ManagerClose::Acquire(handle,token)==ScopeResult::Ok,"foreign inventory owner");Check(Inventory(token).holders==1,"Base, standalone and other manager excluded from target inventory");std::atomic_bool ran{};Close::InvokeControl(otherVm,[&]{ran=true;});Check(ran,"target close leaves other native host operational");}
/** @summary Abandon and fail actual preparation with exact native generation reuse evidence. @param package Actual Base. */
void AbortAndStale(const std::filesystem::path& package){Fixture fixture(package);std::weak_ptr<ScriptRuntime> old;std::uint64_t generation{};{auto plan=fixture.Candidate();auto vm=Preparation::Vm(plan);old=vm;generation=Close::Controls(vm).generation;}Check(old.expired(),"abandoned prepared VM has no inventory ownership cycle");auto next=fixture.Candidate();Check(Close::Controls(Preparation::Vm(next)).generation!=generation,"reused capacity has nonreused VM generation");fixture.Write("error('isolated initialization failure')");bool failed{};try{static_cast<void>(fixture.Candidate());}catch(const std::runtime_error&){failed=true;}Check(failed,"actual initialization failure rejects before enrollment");fixture.Write();auto recovered=fixture.Candidate();Check(Preparation::Binding(*fixture.manager,Preparation::Vm(recovered))==ScopeResult::Ok,"actual capacity available after initialization abort");auto capture=fixture.Capture();std::weak_ptr<ScriptRuntime> stale;Preparation::BeforeBind([&](const std::shared_ptr<ScriptRuntime>& vm){stale=vm;auto writer=fixture.domain->ReserveWriter();Check(writer.Acquired()&&writer.Advance()!=0,"real D invalidation after first Current");});bool denied{};try{auto plan=Publication::Candidate(*fixture.manager,capture,fixture.base);}catch(const std::runtime_error& error){denied=std::string_view(error.what())=="preparation.stale";}Preparation::BeforeBind({});Check(denied&&stale.expired(),"second Current rejects bound stale unexposed candidate and cleans exact VM");Check(fixture.domain->Revision()==1&&!fixture.manager->Snapshot().front().scriptRunning,"only intended stale witness advanced D, no activation");}
/** @summary Bind original factual references without minting a new permission. @param fixture Actual host. @param endpoint Original endpoint. @return Original factual context. */
SemanticContextLease Facts(Fixture& fixture,const std::shared_ptr<SemanticEndpoint>& endpoint){copied::Envelope input;Check(fixture.bridge->Values()->Decode(R"({"v":1,"schema":"test.echo@1","value":["ref","city","7","3"]})","test.echo@1",endpoint->storageOwner,input)==copied::Status::Ok,"native factual copied input");SemanticContextLease result;Check(fixture.bridge->BindReferences(*endpoint,input,result)==ScopeResult::Ok,"original factual lease");return result;}
/** @summary Commit one original prepared transaction with bounded existing native Busy handling. @param plan Exact transaction. */
void Commit(ManagerPublication::Plan& plan){ScopeResult result=ScopeResult::Busy;for(unsigned i=0;i!=4096&&result==ScopeResult::Busy;++i){result=Publication::Commit(plan);if(result==ScopeResult::Busy)std::this_thread::yield();}Check(result==ScopeResult::Ok,"actual original-host joint publication");}
/** @summary Preserve actual initial/handoff publication with early same-host enrollment and separate old generation. @param package Actual Base. */
void JointLifecycle(const std::filesystem::path& package){Fixture fixture(package);auto first=fixture.Candidate();auto oldVm=Preparation::Vm(first);auto oldScope=Preparation::Scope(first);auto oldEndpoint=Preparation::Endpoint(first);oldScope->SetReadiness(true);auto oldGrant=RuntimeScopeTestAccess::Issue(*oldScope);auto oldFacts=Facts(fixture,oldEndpoint);ManagerPublication::Plan initial;std::string error;Check(Publication::Prepare(*fixture.manager,std::move(first),{},oldGrant,{},oldFacts,initial,error)==ScopeResult::Ok,"same-host initial preparation accepts early enrollment");Commit(initial);auto second=fixture.Candidate();auto nextVm=Preparation::Vm(second);auto nextScope=Preparation::Scope(second);nextScope->SetReadiness(true);const auto nextGrant=RuntimeScopeTestAccess::Issue(*nextScope);const auto nextFacts=Facts(fixture,Preparation::Endpoint(second));oldGrant=RuntimeScopeTestAccess::Reserve(*oldScope,oldGrant);oldFacts=Facts(fixture,oldEndpoint);ManagerPublication::Plan handoff;Check(Publication::Prepare(*fixture.manager,std::move(second),oldGrant,nextGrant,oldFacts,nextFacts,handoff,error)==ScopeResult::Ok,"same original-host handoff preparation");Commit(handoff);Check(fixture.domain->Revision()==2,"only initial and handoff publication markers");Check(!oldVm->Status().running&&nextVm->Status().running&&Close::Controls(oldVm).generation!=Close::Controls(nextVm).generation,"same textual owner has separate original VM generations");Check(Preparation::Binding(*fixture.manager,oldVm)==ScopeResult::Ok&&Preparation::Binding(*fixture.manager,nextVm)==ScopeResult::Ok,"original retired and current generations retain exact same-host inventory");auto handle=Close::Capture(*fixture.manager);ManagerClose::Request(handle);ManagerClose::Token token;Check(ManagerClose::Acquire(handle,token)==ScopeResult::Ok,"same-ID inventory owner");Check(Inventory(token).holders==2,"retained old and current VM both inventoried once");Check(!Scheduler::Closed(oldVm)&&!Scheduler::Closed(nextVm),"inventory never reclaims either VM");}
/** @summary Scan genuine returned preparation holders across the existing32-slot work bound. @param package Actual Base. */
void Capacity(const std::filesystem::path& package){Fixture fixture(package);auto capture=fixture.Capture();std::vector<ManagerPreparation::Plan> plans;for(unsigned i=0;i!=33;++i)plans.push_back(Publication::Candidate(*fixture.manager,capture,fixture.base));for(const auto& plan:plans)Check(Preparation::Binding(*fixture.manager,Preparation::Vm(plan))==ScopeResult::Ok,"each actual candidate belongs to original host");auto handle=Close::Capture(*fixture.manager);ManagerClose::Request(handle);ManagerClose::Token token;Check(ManagerClose::Acquire(handle,token)==ScopeResult::Ok,"33 holder inventory owner");Check(Inventory(token).holders==33,"33 distinct real candidate generations, Base excluded");plans.erase(plans.begin());Check(Inventory(token).holders==32,"actual original VM disposal changes host inventory");plans.clear();Check(Inventory(token).holders==0,"all abandoned preparations release actual inventory");Check(fixture.base->Ready(),"candidate disposal does not close Base epoch");}
