/** @summary Verify isolated native VM enrollment only. @param argc Argument count. @param argv Actual Base path. @return Zero when every executed oracle passes. */
int main(int argc,char** argv){try{Check(argc==2,"actual pinned Base source argument required");const std::filesystem::path package=argv[1];
    /** @summary Flush named scenario before genuine native pauses. @param label Scenario identity. @param body Actual test. */
    const auto run=[](const char* label,const auto& body){std::cerr<<"VM enrollment begin "<<label<<std::endl;body();};run("returned",[&]{Returned(package);});run("work and locks",[&]{WorkAndLocks(package);});run("close race",[&]{CloseRace(package);});run("foreign",[&]{Foreign(package);});run("abort and stale",[&]{AbortAndStale(package);});run("joint lifecycle",[&]{JointLifecycle(package);});run("capacity",[&]{Capacity(package);});Check(sc13::tests::FailureCount()==0,"shared fixture setup");std::cout<<checks.load()<<" VM enrollment checks passed\n";return 0;
}catch(const std::exception& error){Preparation::BeforeBind({});std::cerr<<error.what()<<'\n';return 1;}}
